from collections import deque

def find_connected_components(grid, start_row, end_row, start_col, end_col):
    """Find all 7-connected components within bounds"""
    components = []
    visited = set()

    for r in range(start_row, end_row):
        for c in range(start_col, end_col):
            if grid[r][c] == 7 and (r,c) not in visited:
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if start_row <= nr < end_row and start_col <= nc < end_col:
                            if grid[nr][nc] == 7 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(component)

    return components

